import{_ as t,c as a,o,ae as n}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Text Area","description":"Text Area","frontmatter":{"title":"Text Area","description":"Text Area"},"headers":[],"relativePath":"guide/field-types/text-area.md","filePath":"guide/field-types/text-area.md"}'),r={name:"guide/field-types/text-area.md"};function l(s,e,i,d,p,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="text-area" tabindex="-1">Text Area <a class="header-anchor" href="#text-area" aria-label="Permalink to &quot;Text Area&quot;">​</a></h1><p>Following the Data Type settings for a table column, change the data type to &quot;Text Area&quot; to add text descriptions in the column. Or, you can decide the data type right from the start when you add a column to the table. From your dashboard, go to the Ninja Tables plugin → Tables (the table where you want to add Column) → Add Column.</p><ul><li>A pop-up form will appear, and you will see the available <strong>Data Type</strong> options here. You can choose from the various data types listed in the below screenshot. <img src="https://ninjatables.com/wp-content/uploads/2022/11/data-types-1024x612.png" alt="table column data types"> Text Area data type allows you to add multiple lines in a cell. There’s no limit to adding the number of lines in a Text Area.</li><li>Go to the <strong>Data Type</strong> option and select the **Text Area **type of the column.</li><li>Now a new column with data type has been added to the table. <img src="https://ninjatables.com/wp-content/uploads/2023/01/text-area-3.png" alt="text area in Ninja Tables"></li><li>Text Area also supports HTML. You can follow the same path in &quot;<a href="https://ninjatables.com/docs/single-line-text-field/" target="_blank" rel="noreferrer">Single Line Text Field</a>&quot; to see how adding HTML in the Text Area works.</li></ul><h2 id="text-area-in-ninja-tables" tabindex="-1">Text Area in Ninja Tables <a class="header-anchor" href="#text-area-in-ninja-tables" aria-label="Permalink to &quot;Text Area in Ninja Tables&quot;">​</a></h2><p>Update the column with a text area and go to the <strong>Preview</strong> of the table. You can add as much text as you want. Here&#39;s an example. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Text-Area.png" alt="Text-Area"> This function works best for product tables where the seller needs to add a detail of the product. This is how you can add a <strong>Text</strong> <strong>Area</strong> data type in your column easily.</p>',5)])])}const x=t(r,[["render",l]]);export{u as __pageData,x as default};
